  function syncCardAppearanceInputs(){CARD_APPEARANCE_FIELDS.forEach((field)=>{const el=document.getElementById(field);if(!el)return;const value=String(editorProfile?.[field]??'');el.value=value;const picker=document.querySelector(`input[type="color"][data-colour-target="${field}"]`);if(picker)picker.value=normaliseHexColour(value)||'#000000';});const layout=document.getElementById('card_layout');if(layout)layout.value=['compact','standard','showcase'].includes(String(editorProfile.card_layout))?editorProfile.card_layout:'standard';const cols=document.getElementById('card_grid_columns');if(cols)cols.value=String(safeCols(editorProfile.card_grid_columns));}
